namespace ghidra.app.plugin.core.function.editor;

using static org.junit.Assert;




using org.junit;

using generic.test;
using ghidra.program.database;
using ghidra.program.database;
using ghidra.program.model.lang;
using ghidra.program.model.listing;

public class VarnodeLocationCellEditorTest : AbstractGenericTest {
	private static readonly int AARCH64_GENERAL_REGISTER_MAX = 30;

	/* @Test */
	public void testAarch64XRegistersUseNumericOrder()
    {
		ProgramBuilder builder = new ProgramBuilder("TestProgram", ProgramBuilder._AARCH64);
		ProgramDB p = builder.getProgram();
		builder.dispose();

		ProgramContext context = p.getProgramContext();
		List<Register> registers = VarnodeLocationCellEditor.getSortedVisibleRegisters(context);

		List<string> xRegisters = new();
		foreach (Register register in registers) {
			if (register.getName().matches("x\\d+")) {
				xRegisters.add(register.getName());
			}
		}

		List<string> expected = new();
		for (int i = 0; i <= AARCH64_GENERAL_REGISTER_MAX; i++) {
			expected.add("x" + i);
		}
		assertEquals(expected, xRegisters);
	}
}
